create table public.attendance_records (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,student_id uuid references public.students(id) on delete restrict,teacher_id uuid references public.teachers(id) on delete restrict,classroom_id uuid not null references public.classrooms(id) on delete restrict,attendance_date date not null,status text not null check(status in('PRESENT','LATE','EXCUSED','ABSENT')),note text,recorded_at timestamptz not null default timezone('utc',now()),created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),check(student_id is not null or teacher_id is not null),unique(tenant_id,student_id,attendance_date),unique(tenant_id,teacher_id,attendance_date));create index attendance_records_tenant_date_idx on public.attendance_records(tenant_id,attendance_date);alter table public.attendance_records enable row level security;revoke all on public.attendance_records from anon,authenticated;create policy attendance_select_tenant on public.attendance_records for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('attendance.read','Read attendance','View attendance records'),('attendance.create','Create attendance','Record attendance'),('attendance.update','Update attendance','Maintain attendance'),('attendance.delete','Delete attendance','Delete attendance records') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'attendance.%' on conflict do nothing;
